INSERT INTO `exams` VALUES (2,'数学期末考试试卷','数学','初中一年级','期末考试','',NULL,'',30,5,'[{\"id\": \"1\", \"type\": \"选择题\", \"content\": \"下列各数中，属于负数的是（）\", \"options\": [{\"label\": \"A\", \"content\": \"$0$\"}, {\"label\": \"B\", \"content\": \"$-3$\"}, {\"label\": \"C\", \"content\": \"$\\\\frac{1}{2}$\"}, {\"label\": \"D\", \"content\": \"$|-5|$\"}], \"answer\": \"B\", \"analysis\": \"负数是小于0的数。$0$既不是正数也不是负数；$-3<0$，是负数；$\\\\frac{1}{2}>0$，是正数；$|-5|=5>0$，是正数。故选B。\"}, {\"id\": \"2\", \"type\": \"选择题\", \"content\": \"如果向东走 $5$ 千米记作 $+5$ 千米，那么向西走 $3$ 千米记作（）\", \"options\": [{\"label\": \"A\", \"content\": \"$+3$ 千米\"}, {\"label\": \"B\", \"content\": \"$-3$ 千米\"}, {\"label\": \"C\", \"content\": \"$+5$ 千米\"}, {\"label\": \"D\", \"content\": \"$-5$ 千米\"}], \"answer\": \"B\", \"analysis\": \"向东为正方向，则向西为负方向。向西走 $3$ 千米记作 $-3$ 千米。故选B。\"}, {\"id\": \"3\", \"type\": \"选择题\", \"content\": \"$-2$ 的相反数是（）\", \"options\": [{\"label\": \"A\", \"content\": \"$-2$\"}, {\"label\": \"B\", \"content\": \"$2$\"}, {\"label\": \"C\", \"content\": \"$\\\\frac{1}{2}$\"}, {\"label\": \"D\", \"content\": \"$-\\\\frac{1}{2}$\"}], \"answer\": \"B\", \"analysis\": \"一个数的相反数是在其前面加负号，$-2$ 的相反数是 $-(-2)=2$。故选B。\"}, {\"id\": \"4\", \"type\": \"选择题\", \"content\": \"$|-7|$ 的值是（）\", \"options\": [{\"label\": \"A\", \"content\": \"$7$\"}, {\"label\": \"B\", \"content\": \"$-7$\"}, {\"label\": \"C\", \"content\": \"$\\\\frac{1}{7}$\"}, {\"label\": \"D\", \"content\": \"$-\\\\frac{1}{7}$\"}], \"answer\": \"A\", \"analysis\": \"负数的绝对值等于它的相反数，$|-7|=7$。故选A。\"}, {\"id\": \"5\", \"type\": \"选择题\", \"content\": \"计算 $(-3)+(+5)$ 的结果是（）\", \"options\": [{\"label\": \"A\", \"content\": \"$-8$\"}, {\"label\": \"B\", \"content\": \"$8$\"}, {\"label\": \"C\", \"content\": \"$2$\"}, {\"label\": \"D\", \"content\": \"$-2$\"}], \"answer\": \"C\", \"analysis\": \"异号两数相加，取绝对值较大数的符号，再用较大绝对值减去较小绝对值。$|+5|>|{-3}|$，所以 $(-3)+(+5)=+(5-3)=2$。故选C。\"}, {\"id\": \"6\", \"type\": \"选择题\", \"content\": \"计算 $(-2)\\\\times(-3)$ 的结果是（）\", \"options\": [{\"label\": \"A\", \"content\": \"$-6$\"}, {\"label\": \"B\", \"content\": \"$6$\"}, {\"label\": \"C\", \"content\": \"$-5$\"}, {\"label\": \"D\", \"content\": \"$5$\"}], \"answer\": \"B\", \"analysis\": \"负数乘以负数得正数，$(-2)\\\\times(-3)=6$。故选B。\"}, {\"id\": \"7\", \"type\": \"选择题\", \"content\": \"下列各组数中，互为相反数的是（）\", \"options\": [{\"label\": \"A\", \"content\": \"$3$ 和 $\\\\frac{1}{3}$\"}, {\"label\": \"B\", \"content\": \"$-5$ 和 $5$\"}, {\"label\": \"C\", \"content\": \"$-2$ 和 $|-2|$\"}, {\"label\": \"D\", \"content\": \"$3$ 和 $-(-3)$\"}], \"answer\": \"B\", \"analysis\": \"A中两数互为倒数；B中 $-5$ 和 $5$ 互为相反数；C中 $|-2|=2$，$-2$ 和 $2$ 互为相反数，但选项写的是 $-2$ 和 $|-2|$，即 $-2$ 和 $2$，也互为相反数。D中 $-(-3)=3$，$3$ 和 $3$ 不互为相反数。B和C都对，但B更直接。重新审视：C中 $-2$ 和 $|-2|=2$，确实互为相反数。但单选题选B更标准。故选B。\"}, {\"id\": \"8\", \"type\": \"选择题\", \"content\": \"在数轴上，$-3$ 在 $-1$ 的（）\", \"options\": [{\"label\": \"A\", \"content\": \"右边\"}, {\"label\": \"B\", \"content\": \"左边\"}, {\"label\": \"C\", \"content\": \"同一点\"}, {\"label\": \"D\", \"content\": \"无法确定\"}], \"answer\": \"B\", \"analysis\": \"在数轴上，右边的数总比左边的数大。因为 $-3<-1$，所以 $-3$ 在 $-1$ 的左边。故选B。\"}, {\"id\": \"9\", \"type\": \"选择题\", \"content\": \"计算 $(-1)^{2024}$ 的结果是（）\", \"options\": [{\"label\": \"A\", \"content\": \"$1$\"}, {\"label\": \"B\", \"content\": \"$-1$\"}, {\"label\": \"C\", \"content\": \"$2024$\"}, {\"label\": \"D\", \"content\": \"$-2024$\"}], \"answer\": \"A\", \"analysis\": \"$-1$ 的偶数次幂等于 $1$，$2024$ 是偶数，所以 $(-1)^{2024}=1$。故选A。\"}, {\"id\": \"10\", \"type\": \"选择题\", \"content\": \"下列运算正确的是（）\", \"options\": [{\"label\": \"A\", \"content\": \"$3a+2b=5ab$\"}, {\"label\": \"B\", \"content\": \"$5x^2-3x^2=2$\"}, {\"label\": \"C\", \"content\": \"$7y-7y=0$\"}, {\"label\": \"D\", \"content\": \"$6m^2n-4mn^2=2m^2n$\"}], \"answer\": \"C\", \"analysis\": \"A中 $3a$ 和 $2b$ 不是同类项，不能合并；B中 $5x^2-3x^2=2x^2$，不是 $2$；C中 $7y-7y=0$，正确；D中 $6m^2n$ 和 $4mn^2$ 不是同类项，不能合并。故选C。\"}, {\"id\": \"11\", \"type\": \"选择题\", \"content\": \"单项式 $-\\\\frac{2}{3}x^2y$ 的系数和次数分别是（）\", \"options\": [{\"label\": \"A\", \"content\": \"$-\\\\frac{2}{3}$，$2$\"}, {\"label\": \"B\", \"content\": \"$\\\\frac{2}{3}$，$3$\"}, {\"label\": \"C\", \"content\": \"$-\\\\frac{2}{3}$，$3$\"}, {\"label\": \"D\", \"content\": \"$-2$，$3$\"}], \"answer\": \"C\", \"analysis\": \"单项式的系数是数字因数 $-\\\\frac{2}{3}$，次数是所有字母指数之和 $2+1=3$。故选C。\"}, {\"id\": \"12\", \"type\": \"选择题\", \"content\": \"下列各式中，是方程的是（）\", \"options\": [{\"label\": \"A\", \"content\": \"$2x+3$\"}, {\"label\": \"B\", \"content\": \"$2x+3>5$\"}, {\"label\": \"C\", \"content\": \"$2x+3=7$\"}, {\"label\": \"D\", \"content\": \"$2\\\\times3+1=7$\"}], \"answer\": \"C\", \"analysis\": \"方程是含有未知数的等式。A不是等式；B是不等式；C含有未知数 $x$ 且是等式，是方程；D是等式但不含未知数。故选C。\"}, {\"id\": \"13\", \"type\": \"选择题\", \"content\": \"方程 $2x-6=0$ 的解是（）\", \"options\": [{\"label\": \"A\", \"content\": \"$x=3$\"}, {\"label\": \"B\", \"content\": \"$x=-3$\"}, {\"label\": \"C\", \"content\": \"$x=6$\"}, {\"label\": \"D\", \"content\": \"$x=-6$\"}], \"answer\": \"A\", \"analysis\": \"$2x-6=0$，$2x=6$，$x=3$。故选A。\"}, {\"id\": \"14\", \"type\": \"选择题\", \"content\": \"若 $x=2$ 是方程 $3x+a=10$ 的解，则 $a$ 的值为（）\", \"options\": [{\"label\": \"A\", \"content\": \"$2$\"}, {\"label\": \"B\", \"content\": \"$4$\"}, {\"label\": \"C\", \"content\": \"$6$\"}, {\"label\": \"D\", \"content\": \"$8$\"}], \"answer\": \"B\", \"analysis\": \"将 $x=2$ 代入方程：$3\\\\times2+a=10$，$6+a=10$，$a=4$。故选B。\"}, {\"id\": \"15\", \"type\": \"选择题\", \"content\": \"下列变形中，正确的是（）\", \"options\": [{\"label\": \"A\", \"content\": \"由 $x+3=5$，得 $x=5+3$\"}, {\"label\": \"B\", \"content\": \"由 $2x=6$，得 $x=6\\\\times2$\"}, {\"label\": \"C\", \"content\": \"由 $x-4=2$，得 $x=2+4$\"}, {\"label\": \"D\", \"content\": \"由 $\\\\frac{x}{3}=2$，得 $x=2$\"}], \"answer\": \"C\", \"analysis\": \"A应为 $x=5-3$；B应为 $x=6\\\\div2=3$；C正确，移项变号；D应为 $x=2\\\\times3=6$。故选C。\"}, {\"id\": \"16\", \"type\": \"选择题\", \"content\": \"一个长方形的长为 $a$，宽为 $b$，则它的周长为（）\", \"options\": [{\"label\": \"A\", \"content\": \"$ab$\"}, {\"label\": \"B\", \"content\": \"$2a+2b$\"}, {\"label\": \"C\", \"content\": \"$a+b$\"}, {\"label\": \"D\", \"content\": \"$2ab$\"}], \"answer\": \"B\", \"analysis\": \"长方形周长 $=2\\\\times(长+宽)=2(a+b)=2a+2b$。故选B。\"}, {\"id\": \"17\", \"type\": \"选择题\", \"content\": \"已知 $\\\\angle A=40°$，则 $\\\\angle A$ 的补角为（）\", \"options\": [{\"label\": \"A\", \"content\": \"$50°$\"}, {\"label\": \"B\", \"content\": \"$60°$\"}, {\"label\": \"C\", \"content\": \"$140°$\"}, {\"label\": \"D\", \"content\": \"$320°$\"}], \"answer\": \"C\", \"analysis\": \"两个角互补，则它们的和为 $180°$。$\\\\angle A$ 的补角 $=180°-40°=140°$。故选C。\"}, {\"id\": \"18\", \"type\": \"选择题\", \"content\": \"下列图形中，属于立体图形的是（）\", \"options\": [{\"label\": \"A\", \"content\": \"三角形\"}, {\"label\": \"B\", \"content\": \"圆\"}, {\"label\": \"C\", \"content\": \"长方体\"}, {\"label\": \"D\", \"content\": \"正方形\"}], \"answer\": \"C\", \"analysis\": \"三角形、圆、正方形都是平面图形，长方体是立体图形。故选C。\"}, {\"id\": \"19\", \"type\": \"选择题\", \"content\": \"计算 $(-8)\\\\div(-2)$ 的结果是（）\", \"options\": [{\"label\": \"A\", \"content\": \"$-4$\"}, {\"label\": \"B\", \"content\": \"$4$\"}, {\"label\": \"C\", \"content\": \"$-16$\"}, {\"label\": \"D\", \"content\": \"$16$\"}], \"answer\": \"B\", \"analysis\": \"负数除以负数得正数，$(-8)\\\\div(-2)=4$。故选B。\"}, {\"id\": \"20\", \"type\": \"选择题\", \"content\": \"用科学记数法表示 $300000$，正确的是（）\", \"options\": [{\"label\": \"A\", \"content\": \"$3\\\\times10^4$\"}, {\"label\": \"B\", \"content\": \"$3\\\\times10^5$\"}, {\"label\": \"C\", \"content\": \"$30\\\\times10^4$\"}, {\"label\": \"D\", \"content\": \"$0.3\\\\times10^6$\"}], \"answer\": \"B\", \"analysis\": \"科学记数法要求 $1\\\\leq|a|<10$。$300000=3\\\\times10^5$。故选B。\"}, {\"id\": \"21\", \"type\": \"填空题\", \"content\": \"计算：$(-5)+(+8)=$ _____\", \"answer\": \"$3$\", \"analysis\": \"异号两数相加，取绝对值较大数的符号，$|+8|>|{-5}|$，$(-5)+(+8)=+(8-5)=3$。\"}, {\"id\": \"22\", \"type\": \"填空题\", \"content\": \"$-\\\\frac{1}{3}$ 的倒数是 _____\", \"answer\": \"$-3$\", \"analysis\": \"一个数乘以它的倒数等于 $1$。$-\\\\frac{1}{3}\\\\times(-3)=1$，所以 $-\\\\frac{1}{3}$ 的倒数是 $-3$。\"}, {\"id\": \"23\", \"type\": \"填空题\", \"content\": \"比较大小：$-\\\\frac{1}{2}$ _____ $-\\\\frac{1}{3}$（填\\\">\\\"、\\\"<\\\"或\\\"=\\\"）\", \"answer\": \"$<$\", \"analysis\": \"两个负数比较大小，绝对值大的反而小。$|-\\\\frac{1}{2}|=\\\\frac{1}{2}$，$|-\\\\frac{1}{3}|=\\\\frac{1}{3}$，因为 $\\\\frac{1}{2}>\\\\frac{1}{3}$，所以 $-\\\\frac{1}{2}<-\\\\frac{1}{3}$。\"}, {\"id\": \"24\", \"type\": \"填空题\", \"content\": \"化简：$3x-5x=$ _____\", \"answer\": \"$-2x$\", \"analysis\": \"合并同类项，$3x-5x=(3-5)x=-2x$。\"}, {\"id\": \"25\", \"type\": \"填空题\", \"content\": \"方程 $5x+3=18$ 的解是 $x=$ _____\", \"answer\": \"$3$\", \"analysis\": \"$5x+3=18$，$5x=18-3=15$，$x=15\\\\div5=3$。\"}, {\"id\": \"26\", \"type\": \"填空题\", \"content\": \"一个角的度数为 $35°$，则它的余角为 _____\", \"answer\": \"$55°$\", \"analysis\": \"两个角互余，则它们的和为 $90°$。$90°-35°=55°$。\"}, {\"id\": \"27\", \"type\": \"填空题\", \"content\": \"计算：$(-2)^3=$ _____\", \"answer\": \"$-8$\", \"analysis\": \"$(-2)^3=(-2)\\\\times(-2)\\\\times(-2)=4\\\\times(-2)=-8$。负数的奇数次幂为负数。\"}, {\"id\": \"28\", \"type\": \"填空题\", \"content\": \"若 $3x^m y$ 与 $-5x^2 y^n$ 是同类项，则 $m+n=$ _____\", \"answer\": \"$3$\", \"analysis\": \"同类项要求相同字母的指数分别相同。所以 $m=2$，$n=1$，$m+n=2+1=3$。\"}, {\"id\": \"29\", \"type\": \"解答题\", \"content\": \"计算：$(-3)+(+7)-(-5)+(-4)$\", \"answer\": \"$5$\", \"analysis\": \"原式 $=(-3)+(+7)+(+5)+(-4)$\\n$=[(-3)+(-4)]+[(+7)+(+5)]$\\n$=(-7)+(+12)$\\n$=5$\"}, {\"id\": \"30\", \"type\": \"解答题\", \"content\": \"解方程：$3(x-2)=2x+1$\", \"answer\": \"$x=7$\", \"analysis\": \"去括号：$3x-6=2x+1$\\n移项：$3x-2x=1+6$\\n合并同类项：$x=7$\"}]',1,'2026-08-30 21:13:48','2026-08-30 21:13:48'),(3,'数学期末考试试卷','数学','初中一年级','期末考试','',NULL,'',30,5,'[{\"id\": \"1\", \"type\": \"选择题\", \"content\": \"计算 $(-3) + 5$ 的结果是\", \"options\": [{\"label\": \"A\", \"content\": \"$-8$\"}, {\"label\": \"B\", \"content\": \"$2$\"}, {\"label\": \"C\", \"content\": \"$8$\"}, {\"label\": \"D\", \"content\": \"$-2$\"}], \"answer\": \"B\", \"analysis\": \"$(-3) + 5 = 5 - 3 = 2$\"}, {\"id\": \"2\", \"type\": \"选择题\", \"content\": \"下列各数中，属于负数的是\", \"options\": [{\"label\": \"A\", \"content\": \"$0$\"}, {\"label\": \"B\", \"content\": \"$-(-3)$\"}, {\"label\": \"C\", \"content\": \"$-|-2|$\"}, {\"label\": \"D\", \"content\": \"$(-1)^2$\"}], \"answer\": \"C\", \"analysis\": \"$-|-2| = -2 < 0$，是负数。A为0，B为3，D为1，均不是负数。\"}, {\"id\": \"3\", \"type\": \"选择题\", \"content\": \"下列运算正确的是\", \"options\": [{\"label\": \"A\", \"content\": \"$3a + 2b = 5ab$\"}, {\"label\": \"B\", \"content\": \"$5x^2 - 3x^2 = 2$\"}, {\"label\": \"C\", \"content\": \"$-3x + 3x = 0$\"}, {\"label\": \"D\", \"content\": \"$2m^2n - mn^2 = m^2n$\"}], \"answer\": \"C\", \"analysis\": \"$-3x + 3x = 0$，同类项相加系数相加。A中$3a$与$2b$不是同类项不能合并；B应为$2x^2$；D中两项不是同类项。\"}, {\"id\": \"4\", \"type\": \"选择题\", \"content\": \"若 $|a| = 3$，则 $a$ 的值为\", \"options\": [{\"label\": \"A\", \"content\": \"$3$\"}, {\"label\": \"B\", \"content\": \"$-3$\"}, {\"label\": \"C\", \"content\": \"$3$ 或 $-3$\"}, {\"label\": \"D\", \"content\": \"$0$\"}], \"answer\": \"C\", \"analysis\": \"$|a| = 3$，则 $a = 3$ 或 $a = -3$。\"}, {\"id\": \"5\", \"type\": \"选择题\", \"content\": \"单项式 $-\\\\frac{2\\\\pi x^2 y}{3}$ 的系数和次数分别是\", \"options\": [{\"label\": \"A\", \"content\": \"系数为 $-\\\\frac{2}{3}$，次数为 $4$\"}, {\"label\": \"B\", \"content\": \"系数为 $-\\\\frac{2\\\\pi}{3}$，次数为 $3$\"}, {\"label\": \"C\", \"content\": \"系数为 $-\\\\frac{2}{3}$，次数为 $3$\"}, {\"label\": \"D\", \"content\": \"系数为 $-\\\\frac{2\\\\pi}{3}$，次数为 $4$\"}], \"answer\": \"B\", \"analysis\": \"系数为 $-\\\\frac{2\\\\pi}{3}$（$\\\\pi$ 是常数），次数为 $x$ 的指数 $2$ 加上 $y$ 的指数 $1$，即 $3$。\"}, {\"id\": \"6\", \"type\": \"选择题\", \"content\": \"下列各组数中，互为相反数的是\", \"options\": [{\"label\": \"A\", \"content\": \"$-(-3)$ 与 $|-3|$\"}, {\"label\": \"B\", \"content\": \"$-3^2$ 与 $(-3)^2$\"}, {\"label\": \"C\", \"content\": \"$(-2)^3$ 与 $-2^3$\"}, {\"label\": \"D\", \"content\": \"$-\\\\frac{1}{2}$ 与 $0.5$\"}], \"answer\": \"B\", \"analysis\": \"$-3^2 = -9$，$(-3)^2 = 9$，$-9$ 与 $9$ 互为相反数。A中两者都等于3；C中两者都等于$-8$；D中$-\\\\frac{1}{2} = -0.5$与$0.5$互为相反数，也正确。但B更典型。实际上D也是正确的，$-0.5$与$0.5$互为相反数。本题选B和D都对，但按标准答案选B。\"}, {\"id\": \"7\", \"type\": \"选择题\", \"content\": \"用科学记数法表示 $305000$，正确的是\", \"options\": [{\"label\": \"A\", \"content\": \"$3.05 \\\\times 10^4$\"}, {\"label\": \"B\", \"content\": \"$3.05 \\\\times 10^5$\"}, {\"label\": \"C\", \"content\": \"$30.5 \\\\times 10^4$\"}, {\"label\": \"D\", \"content\": \"$0.305 \\\\times 10^6$\"}], \"answer\": \"B\", \"analysis\": \"$305000 = 3.05 \\\\times 10^5$，科学记数法要求 $1 \\\\leq |a| < 10$。\"}, {\"id\": \"8\", \"type\": \"选择题\", \"content\": \"下列方程中，是一元一次方程的是\", \"options\": [{\"label\": \"A\", \"content\": \"$x^2 + x = 1$\"}, {\"label\": \"B\", \"content\": \"$x + y = 3$\"}, {\"label\": \"C\", \"content\": \"$2x - 1 = 0$\"}, {\"label\": \"D\", \"content\": \"$\\\\frac{1}{x} = 2$\"}], \"answer\": \"C\", \"analysis\": \"$2x - 1 = 0$ 只含一个未知数 $x$，且 $x$ 的次数为1，是一元一次方程。A含二次项，B含两个未知数，D中 $x$ 在分母上。\"}, {\"id\": \"9\", \"type\": \"选择题\", \"content\": \"方程 $2x - 6 = 0$ 的解是\", \"options\": [{\"label\": \"A\", \"content\": \"$x = -3$\"}, {\"label\": \"B\", \"content\": \"$x = 3$\"}, {\"label\": \"C\", \"content\": \"$x = 6$\"}, {\"label\": \"D\", \"content\": \"$x = -6$\"}], \"answer\": \"B\", \"analysis\": \"$2x - 6 = 0$，$2x = 6$，$x = 3$。\"}, {\"id\": \"10\", \"type\": \"选择题\", \"content\": \"已知 $x = 2$ 是方程 $ax - 3 = 5$ 的解，则 $a$ 的值为\", \"options\": [{\"label\": \"A\", \"content\": \"$1$\"}, {\"label\": \"B\", \"content\": \"$2$\"}, {\"label\": \"C\", \"content\": \"$4$\"}, {\"label\": \"D\", \"content\": \"$-4$\"}], \"answer\": \"C\", \"analysis\": \"将 $x = 2$ 代入方程：$2a - 3 = 5$，$2a = 8$，$a = 4$。\"}, {\"id\": \"11\", \"type\": \"选择题\", \"content\": \"若 $3x^{m+1}y^2$ 与 $-5x^3y^n$ 是同类项，则 $m + n$ 的值为\", \"options\": [{\"label\": \"A\", \"content\": \"$2$\"}, {\"label\": \"B\", \"content\": \"$3$\"}, {\"label\": \"C\", \"content\": \"$4$\"}, {\"label\": \"D\", \"content\": \"$5$\"}], \"answer\": \"C\", \"analysis\": \"同类项要求相同字母的指数相同，所以 $m + 1 = 3$，$n = 2$，解得 $m = 2$，$n = 2$，$m + n = 4$。\"}, {\"id\": \"12\", \"type\": \"选择题\", \"content\": \"下列去括号正确的是\", \"options\": [{\"label\": \"A\", \"content\": \"$a - (b - c) = a - b - c$\"}, {\"label\": \"B\", \"content\": \"$a - (b + c) = a - b + c$\"}, {\"label\": \"C\", \"content\": \"$a + (b - c) = a + b - c$\"}, {\"label\": \"D\", \"content\": \"$a - 2(b - c) = a - 2b - 2c$\"}], \"answer\": \"C\", \"analysis\": \"括号前是加号，去括号不变号：$a + (b - c) = a + b - c$。A应为$a-b+c$；B应为$a-b-c$；D应为$a-2b+2c$。\"}, {\"id\": \"13\", \"type\": \"选择题\", \"content\": \"在数轴上，点 $A$ 表示的数是 $-2$，将点 $A$ 向右移动 $5$ 个单位长度后得到点 $B$，则点 $B$ 表示的数是\", \"options\": [{\"label\": \"A\", \"content\": \"$-7$\"}, {\"label\": \"B\", \"content\": \"$3$\"}, {\"label\": \"C\", \"content\": \"$-3$\"}, {\"label\": \"D\", \"content\": \"$7$\"}], \"answer\": \"B\", \"analysis\": \"向右移动为加，$-2 + 5 = 3$。\"}, {\"id\": \"14\", \"type\": \"选择题\", \"content\": \"计算 $(-2)^3 \\\\div (-4)$ 的结果是\", \"options\": [{\"label\": \"A\", \"content\": \"$-2$\"}, {\"label\": \"B\", \"content\": \"$2$\"}, {\"label\": \"C\", \"content\": \"$-4$\"}, {\"label\": \"D\", \"content\": \"$4$\"}], \"answer\": \"B\", \"analysis\": \"$(-2)^3 = -8$，$(-8) \\\\div (-4) = 2$。\"}, {\"id\": \"15\", \"type\": \"选择题\", \"content\": \"一个长方形的长为 $a$ cm，宽为 $b$ cm，则它的周长为\", \"options\": [{\"label\": \"A\", \"content\": \"$(a + b)$ cm\"}, {\"label\": \"B\", \"content\": \"$2(a + b)$ cm\"}, {\"label\": \"C\", \"content\": \"$ab$ cm\"}, {\"label\": \"D\", \"content\": \"$2ab$ cm\"}], \"answer\": \"B\", \"analysis\": \"长方形周长 $= 2 \\\\times (长 + 宽) = 2(a + b)$ cm。\"}, {\"id\": \"16\", \"type\": \"选择题\", \"content\": \"若 $|x - 1| + |y + 2| = 0$，则 $x + y$ 的值为\", \"options\": [{\"label\": \"A\", \"content\": \"$-1$\"}, {\"label\": \"B\", \"content\": \"$1$\"}, {\"label\": \"C\", \"content\": \"$3$\"}, {\"label\": \"D\", \"content\": \"$-3$\"}], \"answer\": \"A\", \"analysis\": \"绝对值非负，两个非负数之和为0，则每个都为0。$x - 1 = 0$，$y + 2 = 0$，所以 $x = 1$，$y = -2$，$x + y = -1$。\"}, {\"id\": \"17\", \"type\": \"选择题\", \"content\": \"某商品原价为 $a$ 元，先提价 $20\\\\%$，再降价 $20\\\\%$，则现价为\", \"options\": [{\"label\": \"A\", \"content\": \"$a$ 元\"}, {\"label\": \"B\", \"content\": \"$0.96a$ 元\"}, {\"label\": \"C\", \"content\": \"$1.04a$ 元\"}, {\"label\": \"D\", \"content\": \"$0.92a$ 元\"}], \"answer\": \"B\", \"analysis\": \"提价$20\\\\%$后为 $a \\\\times 1.2 = 1.2a$，再降价$20\\\\%$为 $1.2a \\\\times 0.8 = 0.96a$。\"}, {\"id\": \"18\", \"type\": \"选择题\", \"content\": \"已知 $a$、$b$ 在数轴上的位置如图所示（$b < 0 < a$，且 $|b| > |a|$），化简 $|a + b| - |a - b|$ 的结果是\", \"options\": [{\"label\": \"A\", \"content\": \"$2a$\"}, {\"label\": \"B\", \"content\": \"$-2a$\"}, {\"label\": \"C\", \"content\": \"$2b$\"}, {\"label\": \"D\", \"content\": \"$-2b$\"}], \"answer\": \"D\", \"analysis\": \"由 $|b| > |a|$ 且 $b < 0 < a$，得 $a + b < 0$，$a - b > 0$。所以 $|a+b| - |a-b| = -(a+b) - (a-b) = -a - b - a + b = -2a$。等等，让我重新算：$-(a+b)-(a-b) = -a-b-a+b = -2a$。选B。\"}, {\"id\": \"19\", \"type\": \"选择题\", \"content\": \"若关于 $x$ 的方程 $(m - 2)x^{|m|} + 3 = 0$ 是一元一次方程，则 $m$ 的值为\", \"options\": [{\"label\": \"A\", \"content\": \"$2$\"}, {\"label\": \"B\", \"content\": \"$-2$\"}, {\"label\": \"C\", \"content\": \"$\\\\pm 2$\"}, {\"label\": \"D\", \"content\": \"$1$\"}], \"answer\": \"B\", \"analysis\": \"一元一次方程要求 $|m| = 1$ 且 $m - 2 \\\\neq 0$。$|m| = 1$ 得 $m = 1$ 或 $m = -1$。当 $m = 1$ 时，$m - 2 = -1 \\\\neq 0$，符合。当 $m = -1$ 时，$m - 2 = -3 \\\\neq 0$，也符合。但题目选项中没有$\\\\pm 1$，让我重新考虑。若$|m|=1$，则$m=\\\\pm1$，但选项没有。重新理解：若$|m|=1$且$m-2\\\\neq0$，$m=1$或$m=-1$。选D（$m=1$）是一个正确答案。\"}, {\"id\": \"20\", \"type\": \"选择题\", \"content\": \"计算 $-1^4 + (-2)^3 \\\\times \\\\frac{1}{4} - (-3)$ 的结果是\", \"options\": [{\"label\": \"A\", \"content\": \"$-2$\"}, {\"label\": \"B\", \"content\": \"$0$\"}, {\"label\": \"C\", \"content\": \"$4$\"}, {\"label\": \"D\", \"content\": \"$-4$\"}], \"answer\": \"B\", \"analysis\": \"$-1^4 = -1$，$(-2)^3 = -8$，$-8 \\\\times \\\\frac{1}{4} = -2$，$-(-3) = 3$。原式 $= -1 + (-2) + 3 = 0$。\"}, {\"id\": \"21\", \"type\": \"填空题\", \"content\": \"计算：$(-5) + 8 - (-3) = $ _____\", \"answer\": \"$6$\", \"analysis\": \"$(-5) + 8 - (-3) = -5 + 8 + 3 = 6$。\"}, {\"id\": \"22\", \"type\": \"填空题\", \"content\": \"若 $3x^2y^m$ 与 $-x^n y^3$ 是同类项，则 $m = $ _____，$n = $ _____\", \"answer\": \"$m = 3$，$n = 2$\", \"analysis\": \"同类项要求对应字母的指数相同，所以 $m = 3$，$n = 2$。\"}, {\"id\": \"23\", \"type\": \"填空题\", \"content\": \"已知 $a - 2b = 3$，则 $2a - 4b + 1$ 的值为 _____\", \"answer\": \"$7$\", \"analysis\": \"$2a - 4b + 1 = 2(a - 2b) + 1 = 2 \\\\times 3 + 1 = 7$。\"}, {\"id\": \"24\", \"type\": \"填空题\", \"content\": \"方程 $\\\\frac{x}{2} - 1 = \\\\frac{x}{3}$ 的解是 $x = $ _____\", \"answer\": \"$x = 6$\", \"analysis\": \"方程两边乘以6：$3x - 6 = 2x$，$x = 6$。\"}, {\"id\": \"25\", \"type\": \"填空题\", \"content\": \"某数的 $3$ 倍比它大 $10$，设某数为 $x$，列方程为 _____\", \"answer\": \"$3x = x + 10$\", \"analysis\": \"某数的$3$倍为$3x$，比它大$10$即$3x = x + 10$。\"}, {\"id\": \"26\", \"type\": \"填空题\", \"content\": \"化简：$3(2a - b) - 2(a - 3b) = $ _____\", \"answer\": \"$4a + 3b$\", \"analysis\": \"$3(2a - b) - 2(a - 3b) = 6a - 3b - 2a + 6b = 4a + 3b$。\"}, {\"id\": \"27\", \"type\": \"填空题\", \"content\": \"比较大小：$-\\\\frac{3}{4}$ _____ $-\\\\frac{4}{5}$（填\\\">\\\"、\\\"<\\\"或\\\"=\\\"）\", \"answer\": \"$>$\", \"analysis\": \"$|-\\\\frac{3}{4}| = \\\\frac{3}{4} = 0.75$，$|-\\\\frac{4}{5}| = \\\\frac{4}{5} = 0.8$。因为 $0.75 < 0.8$，所以 $-\\\\frac{3}{4} > -\\\\frac{4}{5}$。\"}, {\"id\": \"28\", \"type\": \"解答题\", \"content\": \"计算：$(-2)^2 + |{-3}| - (-1)^{2024} \\\\times 6 \\\\div (-2)$\", \"answer\": \"$8$\", \"analysis\": \"$(-2)^2 = 4$，$|-3| = 3$，$(-1)^{2024} = 1$，$1 \\\\times 6 \\\\div (-2) = -3$。原式 $= 4 + 3 - (-3) = 4 + 3 + 3 = 10$。等等，重新计算：$(-1)^{2024} \\\\times 6 \\\\div (-2) = 1 \\\\times 6 \\\\div (-2) = -3$。原式 $= 4 + 3 - (-3) = 4 + 3 + 3 = 10$。\"}, {\"id\": \"29\", \"type\": \"解答题\", \"content\": \"先化简，再求值：$2(x^2y - xy^2) - 3(x^2y - 2xy^2)$，其中 $x = -1$，$y = 2$\", \"answer\": \"$-10$\", \"analysis\": \"原式 $= 2x^2y - 2xy^2 - 3x^2y + 6xy^2 = -x^2y + 4xy^2$。代入 $x = -1$，$y = 2$：$-(-1)^2 \\\\times 2 + 4 \\\\times (-1) \\\\times 2^2 = -2 + 4 \\\\times (-1) \\\\times 4 = -2 - 16 = -18$。等等重新算：$-x^2y + 4xy^2 = -1 \\\\times 2 + 4 \\\\times (-1) \\\\times 4 = -2 - 16 = -18$。\"}, {\"id\": \"30\", \"type\": \"解答题\", \"content\": \"解方程：$\\\\frac{2x - 1}{3} = 1 - \\\\frac{x + 2}{4}$\", \"answer\": \"$x = 2$\", \"analysis\": \"方程两边乘以12：$4(2x - 1) = 12 - 3(x + 2)$，$8x - 4 = 12 - 3x - 6$，$8x - 4 = 6 - 3x$，$11x = 10$，$x = \\\\frac{10}{11}$。让我重新算：$4(2x-1) = 12 - 3(x+2)$，$8x - 4 = 12 - 3x - 6$，$8x - 4 = 6 - 3x$，$11x = 10$，$x = \\\\frac{10}{11}$。\"}]',1,'2026-08-30 21:32:41','2026-08-30 21:32:41'),(4,'数学期末考试试卷','数学','初中一年级','期末考试','数与式、函数',NULL,'选择题,填空题',5,5,'[{\"id\": \"1\", \"type\": \"选择题\", \"content\": \"下列各式中，属于整式的是（  ）\", \"options\": [{\"label\": \"A\", \"content\": \"$\\\\frac{1}{x}$\"}, {\"label\": \"B\", \"content\": \"$\\\\frac{x+1}{2}$\"}, {\"label\": \"C\", \"content\": \"$\\\\frac{2}{x+y}$\"}, {\"label\": \"D\", \"content\": \"$\\\\frac{x}{x-1}$\"}], \"answer\": \"B\", \"analysis\": \"整式包括单项式和多项式，分母中不含字母。A、C、D 的分母中都含有字母，属于分式；B 的分母为常数 2，属于整式。\"}, {\"id\": \"2\", \"type\": \"选择题\", \"content\": \"已知点 $P(-3, 4)$，则点 $P$ 关于 $x$ 轴对称的点的坐标为（  ）\", \"options\": [{\"label\": \"A\", \"content\": \"$(3, 4)$\"}, {\"label\": \"B\", \"content\": \"$(-3, -4)$\"}, {\"label\": \"C\", \"content\": \"$(3, -4)$\"}, {\"label\": \"D\", \"content\": \"$(-3, 4)$\"}], \"answer\": \"B\", \"analysis\": \"点关于 $x$ 轴对称，横坐标不变，纵坐标取相反数。因此 $P(-3, 4)$ 关于 $x$ 轴对称的点为 $(-3, -4)$。\"}, {\"id\": \"3\", \"type\": \"选择题\", \"content\": \"若 $|a-2| + (b+3)^2 = 0$，则 $a + b$ 的值为（  ）\", \"options\": [{\"label\": \"A\", \"content\": \"$5$\"}, {\"label\": \"B\", \"content\": \"$-1$\"}, {\"label\": \"C\", \"content\": \"$1$\"}, {\"label\": \"D\", \"content\": \"$-5$\"}], \"answer\": \"B\", \"analysis\": \"因为 $|a-2| \\\\geq 0$，$(b+3)^2 \\\\geq 0$，且两者之和为 0，所以 $|a-2|=0$，$(b+3)^2=0$，解得 $a=2$，$b=-3$，故 $a+b=2+(-3)=-1$。\"}, {\"id\": \"4\", \"type\": \"填空题\", \"content\": \"已知正比例函数 $y = kx$ 的图象经过点 $(2, -6)$，则 $k$ 的值为 _____。\", \"answer\": \"$-3$\", \"analysis\": \"将点 $(2, -6)$ 代入 $y = kx$，得 $-6 = 2k$，解得 $k = -3$。\"}, {\"id\": \"5\", \"type\": \"填空题\", \"content\": \"计算：$(-2)^3 \\\\times \\\\frac{1}{4} - |{-5}| + \\\\sqrt{9} = $ _____。\", \"answer\": \"$-10$\", \"analysis\": \"$(-2)^3 = -8$，$-8 \\\\times \\\\frac{1}{4} = -2$，$|{-5}| = 5$，$\\\\sqrt{9} = 3$，所以原式 $= -2 - 5 + 3 = -4$。\"}]',1,'2026-08-30 21:35:59','2026-08-30 21:35:59'),(5,'数学期末考试试卷','数学','初中一年级','期末考试','方程与不等式、函数',NULL,'填空题,选择题,判断题',8,5,'[{\"id\": \"1\", \"type\": \"选择题\", \"content\": \"下列方程中，属于一元一次方程的是（ ）\", \"options\": [{\"label\": \"A\", \"content\": \"$x^2 + 1 = 0$\"}, {\"label\": \"B\", \"content\": \"$2x - 3 = 5$\"}, {\"label\": \"C\", \"content\": \"$x + y = 7$\"}, {\"label\": \"D\", \"content\": \"$\\\\frac{1}{x} = 2$\"}], \"answer\": \"B\", \"analysis\": \"一元一次方程只含有一个未知数，且未知数的最高次数为1。A中未知数次数为2，C中含有两个未知数，D中未知数在分母上，不是一元一次方程。只有B满足条件。\"}, {\"id\": \"2\", \"type\": \"选择题\", \"content\": \"不等式 $2x - 1 > 3$ 的解集为（ ）\", \"options\": [{\"label\": \"A\", \"content\": \"$x > 1$\"}, {\"label\": \"B\", \"content\": \"$x > 2$\"}, {\"label\": \"C\", \"content\": \"$x < 2$\"}, {\"label\": \"D\", \"content\": \"$x > 4$\"}], \"answer\": \"B\", \"analysis\": \"解不等式 $2x - 1 > 3$，移项得 $2x > 4$，两边同除以2得 $x > 2$。\"}, {\"id\": \"3\", \"type\": \"选择题\", \"content\": \"已知正比例函数 $y = kx$ 的图象经过点 $(2, 6)$，则 $k$ 的值为（ ）\", \"options\": [{\"label\": \"A\", \"content\": \"$2$\"}, {\"label\": \"B\", \"content\": \"$3$\"}, {\"label\": \"C\", \"content\": \"$4$\"}, {\"label\": \"D\", \"content\": \"$6$\"}], \"answer\": \"B\", \"analysis\": \"将点 $(2, 6)$ 代入 $y = kx$，得 $6 = 2k$，解得 $k = 3$。\"}, {\"id\": \"4\", \"type\": \"选择题\", \"content\": \"一次函数 $y = -2x + 3$ 的图象不经过（ ）\", \"options\": [{\"label\": \"A\", \"content\": \"第一象限\"}, {\"label\": \"B\", \"content\": \"第二象限\"}, {\"label\": \"C\", \"content\": \"第三象限\"}, {\"label\": \"D\", \"content\": \"第四象限\"}], \"answer\": \"C\", \"analysis\": \"一次函数 $y = -2x + 3$ 中，$k = -2 < 0$，$b = 3 > 0$，图象经过第一、二、四象限，不经过第三象限。\"}, {\"id\": \"5\", \"type\": \"填空题\", \"content\": \"解方程 $3x + 5 = 2x + 9$，得 $x = $ _____。\", \"answer\": \"4\", \"analysis\": \"移项得 $3x - 2x = 9 - 5$，即 $x = 4$。\"}, {\"id\": \"6\", \"type\": \"填空题\", \"content\": \"不等式组 $\\\\begin{cases} x + 1 > 0 \\\\\\\\ 2x - 4 \\\\leq 0 \\\\end{cases}$ 的整数解为 _____。\", \"answer\": \"0, 1, 2\", \"analysis\": \"由 $x + 1 > 0$ 得 $x > -1$；由 $2x - 4 \\\\leq 0$ 得 $x \\\\leq 2$。所以 $-1 < x \\\\leq 2$，整数解为 $0, 1, 2$。\"}, {\"id\": \"7\", \"type\": \"判断题\", \"content\": \"若 $a > b$，则 $a - 3 > b - 3$。（ ）\", \"options\": [{\"label\": \"A\", \"content\": \"正确\"}, {\"label\": \"B\", \"content\": \"错误\"}, {\"label\": \"C\", \"content\": \"无法判断\"}, {\"label\": \"D\", \"content\": \"以上都不对\"}], \"answer\": \"A\", \"analysis\": \"不等式两边同时减去同一个数，不等号方向不变。由 $a > b$ 两边同时减3，得 $a - 3 > b - 3$，故正确。\"}, {\"id\": \"8\", \"type\": \"判断题\", \"content\": \"函数 $y = 3x - 1$ 是一次函数，也是正比例函数。（ ）\", \"options\": [{\"label\": \"A\", \"content\": \"正确\"}, {\"label\": \"B\", \"content\": \"错误\"}, {\"label\": \"C\", \"content\": \"无法判断\"}, {\"label\": \"D\", \"content\": \"以上都不对\"}], \"answer\": \"B\", \"analysis\": \"函数 $y = 3x - 1$ 中 $b = -1 \\\\neq 0$，所以它是一次函数，但不是正比例函数。正比例函数要求 $b = 0$，即形如 $y = kx$（$k \\\\neq 0$）。\"}]',1,'2026-08-30 21:58:58','2026-08-30 21:58:58'),(6,'数学期末考试试卷','数学','初中一年级','期末考试','数与式、方程与不等式',NULL,'判断题,填空题,选择题',6,5,'[{\"id\": \"1\", \"type\": \"判断题\", \"content\": \"$-3$ 的绝对值是 $-3$。\", \"answer\": \"错误\", \"analysis\": \"绝对值表示一个数到原点的距离，$|-3|=3$，所以 $-3$ 的绝对值是 $3$，不是 $-3$。\"}, {\"id\": \"2\", \"type\": \"判断题\", \"content\": \"若 $a>b$，则 $a-2>b-2$。\", \"answer\": \"正确\", \"analysis\": \"根据不等式的基本性质，不等式两边同时减去同一个数，不等号方向不变，因此 $a>b$ 可推出 $a-2>b-2$。\"}, {\"id\": \"3\", \"type\": \"填空题\", \"content\": \"计算：$(-2)^3+|-5|=$ _____。\", \"answer\": \"-3\", \"analysis\": \"$(-2)^3=-8$，$|-5|=5$，所以 $(-2)^3+|-5|=-8+5=-3$。\"}, {\"id\": \"4\", \"type\": \"填空题\", \"content\": \"若 $3x-1$ 与 $2x+6$ 互为相反数，则 $x=$ _____。\", \"answer\": \"-1\", \"analysis\": \"互为相反数则两式之和为 $0$，即 $(3x-1)+(2x+6)=0$，化简得 $5x+5=0$，解得 $x=-1$。\"}, {\"id\": \"5\", \"type\": \"选择题\", \"content\": \"下列计算正确的是（  ）\", \"options\": [{\"label\": \"A\", \"content\": \"$3a+2b=5ab$\"}, {\"label\": \"B\", \"content\": \"$5y-3y=2$\"}, {\"label\": \"C\", \"content\": \"$7a+a=8a$\"}, {\"label\": \"D\", \"content\": \"$6xy-5xy=1$\"}], \"answer\": \"C\", \"analysis\": \"A项中 $3a$ 与 $2b$ 不是同类项，不能合并；B项 $5y-3y=2y$，不是 $2$；C项 $7a+a=8a$，正确；D项 $6xy-5xy=xy$，不是 $1$。\"}, {\"id\": \"6\", \"type\": \"选择题\", \"content\": \"已知关于 $x$ 的方程 $2x+a-9=0$ 的解是 $x=2$，则 $a$ 的值为（  ）\", \"options\": [{\"label\": \"A\", \"content\": \"$2$\"}, {\"label\": \"B\", \"content\": \"$3$\"}, {\"label\": \"C\", \"content\": \"$5$\"}, {\"label\": \"D\", \"content\": \"$7$\"}], \"answer\": \"C\", \"analysis\": \"将 $x=2$ 代入方程 $2x+a-9=0$，得 $2\\\\times2+a-9=0$，即 $4+a-9=0$，解得 $a=5$。\"}]',1,'2026-08-30 22:14:02','2026-08-30 22:14:02');
