--
-- Table structure for table `file_records`
--

DROP TABLE IF EXISTS `file_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `file_records` (
  `id` int NOT NULL AUTO_INCREMENT,
  `original_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原始文件名',
  `saved_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '保存的文件名',
  `file_path` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件存储路径',
  `file_size` int NOT NULL COMMENT '文件大小(字节)',
  `download_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '下载地址',
  `uid` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属用户 userid（非唯一，一个用户可有多条记录）',
  `md_file_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '转换后的Markdown文件路径',
  `md_download_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Markdown文件下载地址',
  `oss_md_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS上的Markdown文件地址',
  `oss_word_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS上的Word文件地址',
  `oss_images` mediumtext COLLATE utf8mb4_unicode_ci COMMENT 'OSS上的图片地址列表,逗号分隔（变长，可能很多张图）',
  `zip_source` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源zip文件名',
  `mineru_task_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MinerU 任务ID',
  `mineru_state` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MinerU 任务状态: submitted/done/error',
  `mineru_zip_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MinerU 返回的 zip 下载地址',
  `created_at` datetime DEFAULT NULL COMMENT '上传时间',
  PRIMARY KEY (`id`),
  KEY `ix_file_records_id` (`id`),
  KEY `ix_file_records_uid` (`uid`),
  KEY `ix_file_records_mineru_task_id` (`mineru_task_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
