--
-- Table structure for table `knowledge_point`
--

DROP TABLE IF EXISTS `knowledge_point`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `knowledge_point` (
  `id` int NOT NULL AUTO_INCREMENT,
  `point_id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原始知识点ID',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '知识点名称',
  `parent_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '父节点ID，0表示根节点',
  `course_type_code` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程类型编码',
  `course_type_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程类型名称',
  `has_children` int DEFAULT NULL COMMENT '是否有子节点 0-否 1-是',
  `level` int DEFAULT NULL COMMENT '层级深度 1=根',
  `seq_no` int DEFAULT NULL COMMENT '排序号',
  `enabled` int DEFAULT NULL COMMENT '启用状态',
  `source_create_time` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原始数据创建时间',
  `create_time` datetime DEFAULT (now()) COMMENT '记录创建时间',
  `update_time` datetime DEFAULT (now()) COMMENT '记录更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `point_id` (`point_id`),
  KEY `idx_kp_level` (`level`),
  KEY `idx_kp_course_type` (`course_type_code`),
  KEY `idx_kp_course_level` (`course_type_code`,`level`),
  KEY `idx_kp_parent_id` (`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=16384 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

