--
-- Table structure for table `question_type`
--

DROP TABLE IF EXISTS `question_type`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `question_type` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type_id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原始题型ID',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '题型名称',
  `course_type_code` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程类型编码',
  `course_type_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程类型名称',
  `type_category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '题型分类 objective/subjective',
  `answer_gap` int DEFAULT NULL COMMENT '是否有填空 0-否 1-是',
  `seq_no` int DEFAULT NULL COMMENT '排序号',
  `enabled` int DEFAULT NULL COMMENT '启用状态',
  `create_time` datetime DEFAULT (now()) COMMENT '记录创建时间',
  `update_time` datetime DEFAULT (now()) COMMENT '记录更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `type_id` (`type_id`),
  KEY `idx_qt_course_type` (`course_type_code`)
) ENGINE=InnoDB AUTO_INCREMENT=512 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

